edits.new:
packet_root="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
repo_root="$(cd "$packet_root/../../../.." && pwd -P)"
[[ $# == 2 ]] || { echo "Need exact packet index SHA and explicit containing corrected SOURCE_ROOT" >&2; exit 1; }
[[ "$(cd "$2" && pwd -P)" == "$repo_root" ]] || { echo "SOURCE_ROOT must be this containing corrected checkout" >&2; exit 1; }
python3 "$packet_root/verify-packet.py" "$1" "$repo_root"
benchmark_root="$repo_root/tests/node-compat/foundation-classic-streams/measurement-extension-candidate-v1"

[[ "$build_type" == Release && "$stress" == 0 && "$oom" == 0 && "$entropy_mode" == OFF && "$build_jobs" == 1 && -z "$artifact_tag" ]] || { echo "Benchmark requires Release/OFF/no stress/one job/empty tag" >&2; exit 1; }
for value in "$ticks_enabled" "$path_enabled" "$events_enabled" "$string_decoder_enabled" "$assert_enabled" "$querystring_enabled" "$util_enabled" "$stream_web_enabled"; do
  [[ "$value" == 1 ]] || { echo "Benchmark requires every shared prerequisite" >&2; exit 1; }
done
layer_root="$repo_root/tests/node-compat/foundation-classic-streams/trace-integration-candidate-v1"
